        state['last_tx'], state['last_ty'] = tx, ty
    elif step_count <= 5:
        state['last_tx'], state['last_ty'] = tx, ty
    slots = _rendezvous_slot_intervals(sandbox)
    in_slot = any(lo <= step_count <= hi for (lo, hi) in slots)
    if step_count < 110:
        # Initial guidance to activation zone
        gx, gy = 15.0, 1.35
    elif in_slot:
        # Use target's current position during rendezvous
        gx, gy = tx, ty
    else:
        # During non-slot phases, guide to activation zone
        gx, gy = 15.0, 1.35

    # Calculate force based on target position and velocity
    if in_slot:
